package argojob

import (
	"context"
	"encoding/json"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	wfv1 "github.com/argoproj/argo-workflows/v4/pkg/apis/workflow/v1alpha1"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/client-go/kubernetes/fake"
	ktesting "k8s.io/client-go/testing"
	"k8s.io/utils/ptr"
)

// Fake clients do not run API validation or Priority admission. Exercise both
// against the Pods generated by the live seed/collect and identity constructors.
func TestGeneratedHelperPodsPassKubernetesAdmission(t *testing.T) {
	config := seedTestConfig()
	config.applyDefaults()
	kube := fake.NewClientset()
	kube.PrependReactor("create", "pods", func(action ktesting.Action) (bool, runtime.Object, error) {
		action.(ktesting.CreateAction).GetObject().(*corev1.Pod).UID = "helper-pod"
		return false, nil, nil
	})
	seeder := NewSourceSeeder(kube, func(context.Context, string, string, string, []string, io.Reader, io.Writer, io.Writer) error {
		return nil
	}, config)
	seed, err := seeder.createSeedPodBound(t.Context(), "source-seed", "source-claim")
	if err != nil {
		t.Fatal(err)
	}
	collect, err := seeder.createSeedPodBound(t.Context(), "source-collect", "source-claim")
	if err != nil {
		t.Fatal(err)
	}
	controller := &Controller{kube: kube, config: config}
	wf := &wfv1.Workflow{ObjectMeta: metav1.ObjectMeta{Name: "run", Namespace: config.Namespace, UID: "workflow-id"}}
	identity, err := controller.executorIdentityPod(t.Context(), wf, config.ExecutorServiceAccount)
	if err != nil {
		t.Fatal(err)
	}
	type testCase struct {
		Name             string
		Pod              *corev1.Pod
		RejectPreemption bool
	}
	var cases []testCase
	for _, helper := range []struct {
		name string
		pod  *corev1.Pod
	}{{"seed", seed}, {"collect", collect}, {"identity", identity}} {
		if helper.pod.Spec.PriorityClassName != "" || helper.pod.Spec.PreemptionPolicy != nil {
			t.Fatalf("%s overrides Kubernetes priority defaults", helper.name)
		}
		cases = append(cases, testCase{Name: helper.name, Pod: helper.pod})
		broken := helper.pod.DeepCopy()
		broken.Spec.PreemptionPolicy = ptr.To(corev1.PreemptNever)
		cases = append(cases, testCase{Name: helper.name + "-invalid-preemption", Pod: broken, RejectPreemption: true})
	}
	work := t.TempDir()
	for _, name := range []string{"go.mod", "go.sum", "main.go"} {
		body, err := os.ReadFile(filepath.Join("testdata", "helper-pod-validation", name+".txt"))
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(filepath.Join(work, name), body, 0600); err != nil {
			t.Fatal(err)
		}
	}
	body, err := json.Marshal(cases)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(work, "pods.json"), body, 0600); err != nil {
		t.Fatal(err)
	}
	command := exec.CommandContext(t.Context(), "go", "run", "-mod=readonly", "-p=2", ".", "pods.json")
	command.Dir = work
	out, err := command.CombinedOutput()
	if err != nil {
		t.Fatalf("Kubernetes v1.35.7 helper admission: %v\n%s", err, out)
	}
	if strings.Count(string(out), "PASS ") != len(cases) {
		t.Fatalf("missing validator cases: %s", out)
	}
}
